/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');
import { Star } from "@remotion/shapes";

const { fontFamily: montserratFamily } = loadMontserrat();



export type RafflePromoProps = Record<string, any>;

// Helper to generate SVG path for tickets with cutouts on the sides
const makeTicketPath = (w: number, h: number, biteR: number) =>
  `M 0 0 L ${w} 0 L ${w} ${h / 2 - biteR} A ${biteR} ${biteR} 0 0 0 ${w} ${h / 2 + biteR
  } L ${w} ${h} L 0 ${h} L 0 ${h / 2 + biteR} A ${biteR} ${biteR} 0 0 0 0 ${h / 2 - biteR
  } Z`;

const RafflePromo: React.FC<RafflePromoProps> = ({
  backgroundColor = "#12172B",
  glowColor = "#1D2545",
  primaryColor = "#F2C14E",
  accentColor = "#FFFFFF",
  winAmount = "£50",
  captionLine1 = "INSTANT WINS",
  captionLine2 = "THROUGHOUT",
  ticketCount = 40,
  badgeCount = 10,
  transparentBackground = false,
  durationInSeconds = 15,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // --- GRID CALCULATIONS ---
  const cols = 5;
  const rows = Math.ceil(ticketCount / cols);
  const gridWidth = 860 * s;
  const gap = 20 * s;
  const cellWidth = (gridWidth - gap * (cols - 1)) / cols;
  const cellHeight = 70 * s;
  const gridHeight = rows * cellHeight + (rows - 1) * gap;
  // Center grid in the upper-mid section to leave room for caption
  const gridStartY = (height - gridHeight) * 0.4;
  const gridStartX = (width - gridWidth) / 2;

  // --- RANDOMIZED BADGE PLACEMENT ---
  const badgeIndices = useMemo(() => {
    return Array.from({ length: ticketCount }, (_, i) => ({
      i,
      val: random(`badge-sort-${i}`),
    }))
      .sort((a, b) => a.val - b.val)
      .slice(0, badgeCount)
      .map((x) => x.i);
  }, [ticketCount, badgeCount]);

  // --- PARTICLES GENERATION ---
  const particleData = useMemo(() => {
    return Array.from({ length: 25 }, (_, i) => ({
      angle: (i / 25) * Math.PI * 2 + random(`ang-${i}`) * 0.5,
      distOffset: random(`dist-${i}`) * 200,
      size: 10 + random(`size-${i}`) * 15,
      isStar: random(`type-${i}`) > 0.5,
    }));
  }, []);

  // --- TIMING CONSTANTS ---
  const gridSettleFrame = 45; // 1.5s
  const bigRevealStartFrame = 105; // 3.5s

  // --- GLOBAL ANIMATION STATES ---
  // Dim the grid slightly after it settles
  const gridGlobalOpacity = interpolate(
    frame,
    [gridSettleFrame - 10, gridSettleFrame + 10],
    [1, 0.4],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: montserratFamily, overflow: "hidden" }}>
      {/* Background Radial Glow */}
      {!transparentBackground && (
        <div
          style={{
            position: "absolute",
            width: width * 1.5,
            height: width * 1.5,
            left: "50%",
            top: "40%",
            transform: "translate(-50%, -50%)",
            background: `radial-gradient(circle, ${glowColor} 0%, rgba(18,23,43,0) 60%)`,
            transition: "none",
          }}
        />
      )}

      {/* --- BACKGROUND TICKET GRID --- */}
      <div style={{ position: "absolute", width: "100%", height: "100%", opacity: gridGlobalOpacity, transition: "none" }}>
        {Array.from({ length: ticketCount }).map((_, i) => {
          const c = i % cols;
          const r = Math.floor(i / cols);
          const x = gridStartX + c * (cellWidth + gap);
          const y = gridStartY + r * (cellHeight + gap);

          // Stagger grid entrance from bottom up
          const delay = r * 2 + c * 1;
          const ticketEntranceY = interpolate(
            frame - delay,
            [0, 20],
            [height, 0],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );
          const ticketOpacity = interpolate(
            frame - delay,
            [0, 10],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          return (
            <div
              key={`ticket-${i}`}
              style={{
                position: "absolute",
                left: x,
                top: y,
                width: cellWidth,
                height: cellHeight,
                opacity: ticketOpacity,
                transform: `translateY(${ticketEntranceY}px)`,
                transition: "none",
              }}
            >
              <svg width={cellWidth} height={cellHeight} viewBox={`0 0 ${cellWidth} ${cellHeight}`} style={{ position: "absolute" }}>
                <path d={makeTicketPath(cellWidth, cellHeight, 10 * s)} fill={primaryColor} opacity={0.8} />
                <Star points={5} innerRadius={10 * s} outerRadius={20 * s} fill={backgroundColor} style={{ transform: `translate(${cellWidth / 2}px, ${cellHeight / 2}px)`, opacity: 0.3 }} />
              </svg>

              {/* Dotted tear line */}
              <div
                style={{
                  position: "absolute",
                  right: 15 * s,
                  top: 10 * s,
                  bottom: 10 * s,
                  borderRight: `2px dotted ${backgroundColor}`,
                  opacity: 0.3,
                }}
              />
            </div>
          );
        })}
      </div>

      {/* --- POPPING BADGES --- */}
      {badgeIndices.map((ticketIndex, badgeIdx) => {
        const c = ticketIndex % cols;
        const r = Math.floor(ticketIndex / cols);
        const x = gridStartX + c * (cellWidth + gap) + cellWidth / 2;
        const y = gridStartY + r * (cellHeight + gap) + cellHeight / 2;

        const badgeDelay = gridSettleFrame + badgeIdx * 4;
        const localFrame = frame - badgeDelay;

        const scale = spring({ frame: localFrame, fps, config: { damping: 10, mass: 0.8 } });
        const glowScale = interpolate(localFrame, [0, 20], [1, 2], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
        const glowOpacity = interpolate(localFrame, [0, 20], [0.8, 0], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });

        if (localFrame < 0) return null;

        return (
          <div
            key={`badge-${ticketIndex}`}
            style={{
              position: "absolute",
              left: x,
              top: y,
              transition: "none",
            }}
          >
            {/* Expanding Glow Ring */}
            <div
              style={{
                position: "absolute",
                left: -60 * s,
                top: -60 * s,
                width: 120 * s,
                height: 120 * s,
                borderRadius: "50%",
                backgroundColor: accentColor,
                opacity: glowOpacity,
                transform: `scale(${glowScale})`,
                transition: "none",
              }}
            />

            {/* Badge Body */}
            <div
              style={{
                position: "absolute",
                transform: `translate(-50%, -50%) scale(${scale})`,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                filter: "drop-shadow(0px 8px 16px rgba(0,0,0,0.5))",
                transition: "none",
              }}
            >
              <Star
                points={24}
                innerRadius={36 * s}
                outerRadius={42 * s}
                fill={primaryColor}
                stroke={accentColor}
                strokeWidth={2 * s}
                style={{ position: "absolute" }}
              />
              <div
                style={{
                  position: "relative",
                  color: backgroundColor,
                  fontWeight: 900,
                  fontSize: 14 * s,
                  lineHeight: 1.1,
                  textAlign: "center",
                  zIndex: 1,
                }}
              >
                INSTANT<br />WIN
              </div>
            </div>
          </div>
        );
      })}

      {/* --- THE BIG REVEAL (3.5s onwards) --- */}
      {frame >= bigRevealStartFrame && (() => {
        const revealFrame = frame - bigRevealStartFrame;
        const bigScale = spring({ frame: revealFrame, fps, config: { damping: 14, mass: 1.2 } });
        const flipAngle = interpolate(revealFrame, [0, 20], [180, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

        const bigTicketW = 800 * s;
        const bigTicketH = 400 * s;
        const biteR = 30 * s;

        return (
          <>
            {/* Particles Burst */}
            {particleData.map((p, i) => {
              const pDist = spring({ frame: revealFrame, fps, config: { damping: 15 } }) * (300 * s + p.distOffset * s);
              const px = width / 2 + Math.cos(p.angle) * pDist;
              const py = height * 0.55 + Math.sin(p.angle) * pDist;
              const pOp = interpolate(revealFrame, [10, 40], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
              const pRot = revealFrame * 8 * (i % 2 === 0 ? 1 : -1);

              return (
                <div
                  key={`particle-${i}`}
                  style={{
                    position: "absolute",
                    left: px,
                    top: py,
                    width: p.size * s,
                    height: p.size * s,
                    backgroundColor: p.isStar ? "transparent" : primaryColor,
                    opacity: pOp,
                    transform: `translate(-50%, -50%) rotate(${pRot}deg)`,
                    transition: "none",
                  }}
                >
                  {p.isStar && <Star points={5} innerRadius={p.size * 0.4 * s} outerRadius={p.size * s} fill={accentColor} />}
                </div>
              );
            })}

            {/* Central Big Ticket */}
            <div
              style={{
                position: "absolute",
                left: "50%",
                top: "55%",
                width: bigTicketW,
                height: bigTicketH,
                marginLeft: -bigTicketW / 2,
                marginTop: -bigTicketH / 2,
                transform: `scale(${bigScale}) perspective(1200px) rotateY(${flipAngle}deg)`,
                transformStyle: "preserve-3d",
                transition: "none",
                filter: "drop-shadow(0px 30px 60px rgba(0,0,0,0.6))",
              }}
            >
              {/* Back Face (Visible during flip) */}
              <div
                style={{
                  position: "absolute",
                  inset: 0,
                  backfaceVisibility: "hidden",
                  transform: "rotateY(180deg)",
                  backgroundColor: primaryColor,
                  borderRadius: 20 * s,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                <Star points={8} innerRadius={60 * s} outerRadius={120 * s} fill={backgroundColor} opacity={0.1} />
              </div>

              {/* Front Face */}
              <div
                style={{
                  position: "absolute",
                  inset: 0,
                  backfaceVisibility: "hidden",
                }}
              >
                <svg width={bigTicketW} height={bigTicketH} viewBox={`0 0 ${bigTicketW} ${bigTicketH}`}>
                  <path d={makeTicketPath(bigTicketW, bigTicketH, biteR)} fill={primaryColor} />
                  {/* Decorative dashed tear line on large ticket */}
                  <line
                    x1={bigTicketW - 80 * s}
                    y1={40 * s}
                    x2={bigTicketW - 80 * s}
                    y2={bigTicketH - 40 * s}
                    stroke={backgroundColor}
                    strokeWidth={8 * s}
                    strokeDasharray={`${16 * s} ${16 * s}`}
                    strokeLinecap="round"
                    opacity={0.8}
                  />
                </svg>
                <div
                  style={{
                    position: "absolute",
                    inset: 0,
                    right: 80 * s, // offset for the tear line
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                  }}
                >
                  <span
                    style={{
                      fontSize: 220 * s,
                      fontWeight: 900,
                      color: backgroundColor,
                      letterSpacing: -5 * s,
                      lineHeight: 1,
                    }}
                  >
                    {winAmount}
                  </span>
                </div>
              </div>
            </div>

            {/* Caption Text Below */}
            <div
              style={{
                position: "absolute",
                top: "55%",
                marginTop: bigTicketH / 2 + 80 * s,
                width: "100%",
                textAlign: "center",
                display: "flex",
                flexDirection: "column",
                gap: 10 * s,
              }}
            >
              {[captionLine1, captionLine2].map((text, idx) => {
                const textY = spring({ frame: revealFrame - 15 - idx * 5, fps, config: { damping: 14 } });
                const textOp = interpolate(revealFrame - 15 - idx * 5, [0, 10], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
                return (
                  <div
                    key={`caption-${idx}`}
                    style={{
                      fontSize: 72 * s,
                      fontWeight: 800,
                      color: idx === 0 ? accentColor : primaryColor,
                      opacity: textOp,
                      transform: `translateY(${(1 - textY) * 50}px)`,
                      lineHeight: 1.1,
                      letterSpacing: 2 * s,
                      transition: "none",
                    }}
                  >
                    {text}
                  </div>
                );
              })}
            </div>
          </>
        );
      })()}
    </AbsoluteFill>
  );
};

export default RafflePromo;